const body = $input.first().json.body || $input.first().json;
if (!body.narration_script) throw new Error('narration_script is required');
if (!body.title) throw new Error('title is required');
const config = {
  episode_id:              body.episode_id || `ep_${new Date().getTime()}`,
  title:                   body.title,
  narration_script:        body.narration_script,
  thumbnail_text:          body.thumbnail_text || body.title,
  seo_keywords:            body.seo_keywords || [],
  channel_niche:           body.channel_niche || $env.CHANNEL_NICHE || 'general',
  language:                body.language || $env.CHANNEL_LANGUAGE || 'English',
  visual_style:            body.visual_style || $env.CHANNEL_VISUAL_STYLE || 'cinematic, 16:9',
  scene_seconds:           body.scene_seconds || parseInt($env.SCENE_VIDEO_SECONDS || '8'),
  workspace:               '/data/pipeline'
};
return [{ json: config }];

